import{_ as e,b as i,e as t,a7 as r}from"./chunks/framework.BCCJKnGb.js";const g=JSON.parse('{"title":"保研资料总览","description":"国新系推免资料：时间线、四条路径经验、2024–2026 真题、专题模板与知识框架。","frontmatter":{"title":"保研资料总览","description":"国新系推免资料：时间线、四条路径经验、2024–2026 真题、专题模板与知识框架。","type":"baoyan-index","tags":["保研","推免","国新系"],"updated":"2026-11-07T00:00:00.000Z"},"headers":[],"relativePath":"baoyan/index.md","filePath":"baoyan/index.md","lastUpdated":null}'),n={name:"baoyan/index.md"};function o(s,a,l,d,p,c){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="保研资料总览" tabindex="-1">保研资料总览 <a class="header-anchor" href="#保研资料总览" aria-label="Permalink to &quot;保研资料总览&quot;">​</a></h1><blockquote><p>先记住一句话：<strong>保研 = 拿到本校推免资格 + 通过目标院校接收考核</strong>，两条线并行。</p></blockquote><div class="card-grid"><div class="card"><h3>时间线</h3><p>低年级到大四，每个月该做什么。</p><p><a href="/baoyan/timeline">查看 →</a></p></div><div class="card"><h3>推免要点</h3><p>资格、综合评价、六级、材料清单。</p><p><a href="/baoyan/rules">查看 →</a></p></div><div class="card"><h3>经验分享</h3><p>国新 / 专硕 / 学硕 / 外保四条路径。</p><p><a href="/baoyan/experiences">查看 →</a></p></div><div class="card"><h3>笔试与面试</h3><p>2024–2026 真题与准备方法。</p><p><a href="/baoyan/interview">查看 →</a></p></div><div class="card"><h3>资料库</h3><p>真题、专题模板、知识框架、清华资料。</p><p><a href="/baoyan/materials">查看 →</a></p></div><div class="card"><h3>常见问题</h3><p>排名、夏令营、材料、心态。</p><p><a href="/baoyan/faq">查看 →</a></p></div></div><h2 id="_2026-年分享会核心结论" tabindex="-1">2026 年分享会核心结论 <a class="header-anchor" href="#_2026-年分享会核心结论" aria-label="Permalink to &quot;2026 年分享会核心结论&quot;">​</a></h2><ul><li><strong>双线并行</strong>：本校推免资格 + 目标院校接收考核，缺一不可。</li><li><strong>综合评价</strong>：学业成绩权重最高；科研、素拓是主要加分项。</li><li><strong>国新门槛</strong>：本院报国新方向，<strong>六级 520</strong> 是硬门槛（以当年通知为准）。</li><li><strong>四条路径</strong>：国新、专硕、学硕、外保；准备重点不同，不要一套材料投所有。</li><li><strong>心态</strong>：保研不是唯一选择；专硕分享人明确说“保研并非人生唯一选择”。</li></ul><h2 id="先做三件事" tabindex="-1">先做三件事 <a class="header-anchor" href="#先做三件事" aria-label="Permalink to &quot;先做三件事&quot;">​</a></h2><ol><li>查自己的<strong>绩点排名</strong>和<strong>六级成绩</strong>，确认短板。</li><li>看 <a href="/mingxin-demo/baoyan/timeline">时间线</a>，标出当前学期该做的事。</li><li>做一套 <a href="/mingxin-demo/baoyan/materials">RUC 历年真题</a>，知道自己差在哪。</li></ol><div class="warning custom-block"><p class="custom-block-title">重要提醒</p><p>推免政策每年可能调整。本站是经验与信息汇总，不是学院官方文件；一切以当年学院/教务处通知为准。含姓名、联系方式、具体去向的完整经验不公开。</p></div>',8)])])}const b=e(n,[["render",o]]);export{g as __pageData,b as default};
